import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.C7GIOALF.js";const u=JSON.parse('{"title":"MTG Treachery","description":"","frontmatter":{},"headers":[],"relativePath":"formats/bang-like/variants/treachery.md","filePath":"formats/bang-like/variants/treachery.md","lastUpdated":null}'),n={name:"formats/bang-like/variants/treachery.md"};function s(o,e,l,d,h,c){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="mtg-treachery" tabindex="-1">MTG Treachery <a class="header-anchor" href="#mtg-treachery" aria-label="Permalink to &quot;MTG Treachery&quot;">​</a></h1><p><a href="./../">BANG-like versions</a> · <strong>Rules: published Treachery rules, May 3, 2026</strong></p><p>Treachery adds Identity cards to an underlying multiplayer format, usually Commander. This page records the setup, Identity rules, unveil procedure, team rules, and end-of-game exceptions. Individual Identity abilities still use their card text.</p><h2 id="players-decks-and-materials" tabindex="-1">Players, decks, and materials <a class="header-anchor" href="#players-decks-and-materials" aria-label="Permalink to &quot;Players, decks, and materials&quot;">​</a></h2><p>Play with at least four players. The introductory page recommends five to seven; the comprehensive rules describe five or six as ideal.</p><p>Choose the underlying format and decks <strong>before</strong> preparing the Identity deck. For Commander, use normal Commander decks, command zones, commander tax, and commander damage. Treachery uses free-for-all turns, allows attacks against multiple players, and uses neither limited range of influence nor the deploy-creatures option.</p><p>Prepare exactly one Identity card per player. Identity rarity indicates complexity rather than power: uncommon is recommended for first games, rare for advanced play, mythic for expert play, and purple/special for deliberately chaotic identities.</p><h2 id="preparing-the-identity-deck" tabindex="-1">Preparing the Identity deck <a class="header-anchor" href="#preparing-the-identity-deck" aria-label="Permalink to &quot;Preparing the Identity deck&quot;">​</a></h2><p>The general construction rule calls for exactly one Leader, at least one Traitor, and Assassins equal to half the player count rounded down. Fill the remaining places with Guardians or Traitors.</p><p>The source also publishes this recommended table:</p><table tabindex="0"><thead><tr><th>Players</th><th style="text-align:right;">Leader</th><th style="text-align:right;">Traitor</th><th style="text-align:right;">Assassins</th><th style="text-align:right;">Guardians</th></tr></thead><tbody><tr><td>4</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td style="text-align:right;">2</td><td style="text-align:right;">0</td></tr><tr><td>5</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td style="text-align:right;">2</td><td style="text-align:right;">1</td></tr><tr><td>6</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td style="text-align:right;">3</td><td style="text-align:right;">1</td></tr><tr><td>7</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td style="text-align:right;">3</td><td style="text-align:right;">2</td></tr><tr><td>8</td><td style="text-align:right;">1</td><td style="text-align:right;">2</td><td style="text-align:right;">3</td><td style="text-align:right;">2</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Eight-player source discrepancy</p><p>The published eight-player row uses three Assassins; the general half-rounded-down formula gives four. Both appear in the current source. Choose the recommended row or a formula-based distribution before preparing an eight-player game, and announce the distribution. Do not accidentally combine them.</p></div><p>The role distribution is public information before the game, except in the optional Backstab Rumble setup below.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><ol><li>Choose decks, the Identity selection, and the role distribution.</li><li>Shuffle the Identity deck and deal one Identity face down to each player.</li><li>Players privately inspect their own Identity.</li><li>Put each Identity in its owner&#39;s command zone. An Identity with unveil starts face down; an Identity without unveil starts face up.</li><li>Prepare the underlying game. Starting life is <strong>20</strong>, or <strong>40 for Commander</strong>, unless an Identity or the underlying format changes it. The normal opening hand is <strong>seven</strong>, subject to those same exceptions.</li><li>The player with the face-up Leader Identity takes the first turn. If effects designate several starting players, randomly choose among them.</li></ol><p>Other roles remain secret while their Identities are face down. Do not reveal one just to prove a claim.</p><h2 id="identity-cards-and-abilities" tabindex="-1">Identity cards and abilities <a class="header-anchor" href="#identity-cards-and-abilities" aria-label="Permalink to &quot;Identity cards and abilities&quot;">​</a></h2><p>Identity is a nontraditional card type. An Identity:</p><ul><li>Stays in the command zone for the entire game. If it would leave that zone, it remains there.</li><li>Is not a permanent, cannot be cast, and does not go into an ordinary deck.</li><li>Can be introduced from outside the game by an effect that specifically permits it.</li><li>Is initially owned by the player who started with it in their command zone, and controlled by that owner.</li><li>Can have multiple Identity subtypes: Leader, Guardian, Assassin, and Traitor.</li><li>Has no characteristics while face down.</li><li>Can be inspected by its controller at any time. Other players cannot inspect it without permission from an effect.</li></ul><p>A face-up Identity&#39;s static, activated, and triggered abilities function from the command zone. An ability referring to “this identity” refers to its own source card there. A reference to a particular role&#39;s “player” means a player controlling a <strong>face-up</strong> Identity with that subtype. Some abilities modify the pregame procedure itself.</p><h2 id="unveil-complete-procedure" tabindex="-1">Unveil: complete procedure <a class="header-anchor" href="#unveil-complete-procedure" aria-label="Permalink to &quot;Unveil: complete procedure&quot;">​</a></h2><p>An unveil ability makes the Identity start face down and makes it turn face up when its controller loses.</p><p>To unveil voluntarily:</p><ol><li>Wait until you have priority.</li><li>Check any restriction on the Identity, including undercover.</li><li>Show what the Identity&#39;s unveil cost would be face up.</li><li>Choose any required value of X and pay that cost.</li><li>Turn the Identity face up. Its normal characteristics return.</li><li>Put any abilities triggered by this unveil onto the stack at the appropriate time.</li></ol><p>Unveiling is a <strong>special action</strong>. It does not use the stack and cannot itself be responded to. The triggered abilities produced by it do use the stack and can be responded to.</p><p>An Identity without an unveil cost cannot be turned face up using this procedure. If another ability refers to X in the unveil cost, it uses the value chosen while unveiling.</p><p>An “as this Identity is unveiled” effect applies during the turn-face-up action. A “when unveiled” ability triggers only from turning it face up through the unveil special action; merely revealing it on elimination does not perform that action.</p><h2 id="undercover" tabindex="-1">Undercover <a class="header-anchor" href="#undercover" aria-label="Permalink to &quot;Undercover&quot;">​</a></h2><p>An undercover restriction permits unveiling only after at least one of these has happened:</p><ul><li>Another non-Leader Identity has been revealed.</li><li>A player other than you has attacked a Leader player this game.</li></ul><p>For the second condition, a creature must actually have been declared as an attacker against the Leader. Putting a creature onto the battlefield already attacking does not count as declaring that attack.</p><h2 id="copying-and-turning-face-up" tabindex="-1">Copying and turning face up <a class="header-anchor" href="#copying-and-turning-face-up" aria-label="Permalink to &quot;Copying and turning face up&quot;">​</a></h2><p>When an Identity turns face up, use its normal copiable values again while continuing to apply effects already affecting it.</p><p>A face-down Identity that copies another Identity still has the characteristics imposed by being face down. When it later turns face up, it shows the copied values. Apply the usual Magic copying rules together with these Identity rules.</p><h2 id="teams-and-opponents" tabindex="-1">Teams and opponents <a class="header-anchor" href="#teams-and-opponents" aria-label="Permalink to &quot;Teams and opponents&quot;">​</a></h2><ul><li>Face-up Leaders and Guardians form the <strong>Leader team</strong>.</li><li>Face-up Assassins form the <strong>Assassin team</strong>.</li><li>Each Traitor forms a separate team and has no teammates, including other Traitors.</li><li>A player with a face-down Identity has no teammates and is an opponent of the other players until it is face up.</li></ul><p>This distinction matters for effects referring to an opponent or teammate. Do not treat a hidden Guardian as a face-up teammate for targeting or card effects merely because you suspect their role.</p><p>Turns remain individual. Treachery does not grant shared turns, shared life totals, or shared mana.</p><h2 id="winning-and-losing" tabindex="-1">Winning and losing <a class="header-anchor" href="#winning-and-losing" aria-label="Permalink to &quot;Winning and losing&quot;">​</a></h2><p>Normal Magic game-ending rules continue to apply, with these team conditions and exceptions:</p><ol><li>A team loses when all of its players have lost.</li><li>The Leader team loses when all players controlling Leader Identities have lost, even if Guardians remain. This overrides an effect that would otherwise stop a Guardian from losing.</li><li>The Assassin team wins when all Leaders have lost and at least one Assassin Identity remains in the game.</li><li>A Traitor wins when every opponent has left, including every other Traitor.</li><li>If a player on a team wins, the entire team wins.</li></ol><p>A Traitor therefore usually needs the Assassins eliminated before removing the Leader. Simply killing the Leader while an Assassin can claim the victory does not fulfill the Traitor&#39;s objective.</p><h2 id="leaving-the-game" tabindex="-1">Leaving the game <a class="header-anchor" href="#leaving-the-game" aria-label="Permalink to &quot;Leaving the game&quot;">​</a></h2><p>Reveal all face-down Identities controlled by a departing player. The game remembers that player&#39;s last team using their last known Identity.</p><p>Apply normal multiplayer removal of that player&#39;s owned objects, with two Identity exceptions:</p><ul><li>An ability already on the stack whose source is an Identity and whose owner leaves remains on the stack. Let the departing player resolve it if possible.</li><li>An Identity owned by the departing player but controlled by someone still in the game stays. Its remaining controller becomes its new owner.</li></ul><p>At the end of the game, reveal every remaining face-down Identity.</p><h2 id="optional-setups" tabindex="-1">Optional setups <a class="header-anchor" href="#optional-setups" aria-label="Permalink to &quot;Optional setups&quot;">​</a></h2><h3 id="simple-role-cards" tabindex="-1">Simple role cards <a class="header-anchor" href="#simple-role-cards" aria-label="Permalink to &quot;Simple role cards&quot;">​</a></h3><p>The source offers basic lands instead of custom Identities: Plains for Leader, Island for Guardian, Mountain for Assassin, and Swamp for Traitor. Use the chosen distribution and role objectives. This simplified option supplies roles without the custom cards&#39; unveil effects; the land&#39;s ordinary text is not an Identity ability.</p><h3 id="backstab-rumble" tabindex="-1">Backstab Rumble <a class="header-anchor" href="#backstab-rumble" aria-label="Permalink to &quot;Backstab Rumble&quot;">​</a></h3><p>Prepare exactly one Leader and make <strong>every other Identity a Traitor</strong>. Each Traitor still acts alone and must outlast every opponent, including other Traitors.</p><p>The source allows this option to be kept secret from players for surprise, overriding its usual public-distribution instruction. It changes the setup, not the Identity, unveil, or last-survivor procedures above.</p><h2 id="card-restrictions-and-materials" tabindex="-1">Card restrictions and materials <a class="header-anchor" href="#card-restrictions-and-materials" aria-label="Permalink to &quot;Card restrictions and materials&quot;">​</a></h2><p>Use the underlying format&#39;s banned/restricted list. The Treachery source additionally recommends avoiding Expropriate, Head Games, and Trade Secrets unless everyone agrees; that agreement cannot make a card legal in a base format that already bans it.</p><ul><li><a href="./../sources/treachery-cards/">Local card materials and archived oracle</a></li><li><a href="https://mtgtreachery.net/rules/oracle/" target="_blank" rel="noreferrer">Current Treachery card oracle</a></li><li><a href="https://mtgtreachery.net/en/#download" target="_blank" rel="noreferrer">Printable cards</a></li></ul><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><p><a href="https://mtgtreachery.net/en/" target="_blank" rel="noreferrer">Treachery&#39;s play instructions</a> and <a href="https://mtgtreachery.net/rules/cr/" target="_blank" rel="noreferrer">comprehensive rules</a>, checked October 18, 2026. <a href="./../sources/mtg-treachery.html">Archived research notes</a>.</p>',58)])])}const m=t(n,[["render",s]]);export{u as __pageData,m as default};
